namespace Utility {
    struct Handle {};
    void release(Handle) {} // Function 1 (ADL target)
}

namespace App {
    void release(int) {} // Function 2 (Standard lookup target)

    void invoke() {
        // Standard Lookup (Current/Outer scope)
        release(10);          // Uses Function 2

        // ADL (Argument-Dependent Lookup)
        Utility::Handle h;
        release(h);           // Finds Utility::release(Handle)
    }
}
// ADL searches namespaces associated with argument types
// ONLY for unqualified function calls.
